namespace sv_7723fb785b9e45db89c56c17c98526df.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds theme state per circuit.
/// Interactive components subscribe to OnChanged to re-render when theme changes.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever Theme or AccentColor changes.
    /// Subscribers must call InvokeAsync + StateHasChanged on the UI thread.
    /// </summary>
    public event Action? OnChanged;

    /// <summary>
    /// Bulk-set both properties without firing twice.
    /// </summary>
    public void SetPreferences(ThemeMode theme, string accentColor)
    {
        bool changed = false;
        if (_theme != theme) { _theme = theme; changed = true; }
        if (_accentColor != accentColor) { _accentColor = accentColor; changed = true; }
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChanged?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += OnThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Rehydrate from cookie on first interactive render
            var cookie = await JS.InvokeAsync<string>("eval",
                "document.cookie.split('; ').find(c => c.startsWith('theme_prefs='))?.split('=')[1] || ''");

            if (!string.IsNullOrEmpty(cookie))
            {
                var parts = Uri.UnescapeDataString(cookie).Split('|');
                if (parts.Length == 2
                    && Enum.TryParse<ThemeMode>(parts[0], out var mode))
                {
                    ThemeService.SetPreferences(mode, parts[1]);
                }
            }
        }
    }

    private void OnThemeChanged()
    {
        InvokeAsync(async () =>
        {
            // Persist to cookie so it survives across circuits
            var value = $"{ThemeService.Theme}|{ThemeService.AccentColor}";
            await JS.InvokeVoidAsync("eval",
                $"document.cookie='theme_prefs={Uri.EscapeDataString(value)};path=/;max-age=31536000'");
            StateHasChanged();
        });
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose() => ThemeService.OnChanged -= OnThemeChanged;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px; border-left: 4px solid @ThemeService.AccentColor;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button type="button"
                    class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.Theme = mode">
                @mode
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="OnAccentChanged" />
        <span style="color: @ThemeService.AccentColor; font-weight: bold;">
            @ThemeService.AccentColor
        </span>
